     * 쪽의 글자.
     */
    func extractText(sessionId: UInt64, page: UInt32) throws  -> String
    
    /**
     * 문서에서 글자를 찾는다(대소문자·공백 종류는 가리지 않는다). 쪽 순서로 `max` 개까지.
     * 찾는 동안 다시 부르면 앞의 찾기는 빈 목록으로 끝난다(글자를 칠 때마다 불러도 된다).
