/**
 * 엔진 오류. 메시지는 개발자용(영어)이며 화면 글자는 앱이 종류에 맞춰 고른다.
 */
public 
enum PapyError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    /**
     * 인자가 잘못됨
     */
    case InvalidArgument(detail: String
    )
    /**
     * 읽기 실패
     */
    case Io(detail: String
    )
    /**
     * 지원하지 않는 형식(모바일 엔진은 PDF 를 열지 않는다)
     */
    case UnsupportedFormat(detail: String
    )
    /**
     * 손상된 문서
     */
    case InvalidDocument(detail: String
    )
    /**
     * 암호가 필요하거나 틀림
     */
    case PasswordRequired(detail: String
    )
    /**
     * 크기·쪽 수 상한 초과
     */
    case LimitExceeded(detail: String
    )
    /**
     * 없는 쪽
     */
    case PageOutOfRange(detail: String
    )
    /**
     * 아직 안 되는 기능
     */
    case NotImplemented(detail: String
    )
    /**
     * 닫혔거나 없는 문서
     */
    case SessionNotFound(detail: String
    )
    /**
     * 그 밖의 내부 오류
     */
    case Internal(detail: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension PapyError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypePapyError: FfiConverterRustBuffer {
    typealias SwiftType = PapyError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> PapyError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .InvalidArgument(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 2: return .Io(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 3: return .UnsupportedFormat(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 4: return .InvalidDocument(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 5: return .PasswordRequired(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 6: return .LimitExceeded(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 7: return .PageOutOfRange(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 8: return .NotImplemented(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 9: return .SessionNotFound(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 10: return .Internal(
            detail: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: PapyError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .InvalidArgument(detail):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .Io(detail):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .UnsupportedFormat(detail):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .InvalidDocument(detail):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .PasswordRequired(detail):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .LimitExceeded(detail):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .PageOutOfRange(detail):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .NotImplemented(detail):
            writeInt(&buf, Int32(8))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .SessionNotFound(detail):
            writeInt(&buf, Int32(9))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .Internal(detail):
            writeInt(&buf, Int32(10))
            FfiConverterString.write(detail, into: &buf)
            
        }
    }
}


